#include "ksEditSceneTask.h"
#include <array>
#include <cstdint>
#include <iostream>
#include <stdexcept>
#include <vector>
using T=ks::EditSceneTask;using S=T::Stage;using C=T::Child;using K=T::Kind;
void check(bool b,const char*m){if(!b)throw std::runtime_error(m);}int main(){try{uint64_t cases=0;auto verify=[&](unsigned kind,unsigned parameter,unsigned value,unsigned save,unsigned bank,unsigned previous,unsigned duplicate){T t{K(kind),save!=0};std::array<uint8_t,256>patch{},expectedPatch{};std::array<uint8_t,16>snapshot{},expectedSnapshot{},indices{},values{};std::array<uint8_t,64>edit{},backup{};for(unsigned i=0;i<256;++i)patch[i]=uint8_t(i*17+value);for(unsigned i=0;i<16;++i){snapshot[i]=uint8_t(i*19+parameter);indices[i]=uint8_t(parameter+i*(duplicate?0:17));values[i]=uint8_t(value+i*13);}for(unsigned i=0;i<64;++i){edit[i]=uint8_t(i*7+bank);backup[i]=uint8_t(i*11+previous);}auto expectedEdit=edit,expectedBackup=backup;expectedPatch=patch;expectedSnapshot=snapshot;unsigned storedPrevious=previous,selected=bank,loads=0,applies=0,notify=0,copyWrites=0;
if(kind==0)storedPrevious=bank;else if(kind==1){for(unsigned i=0;i<16;++i)if(values[i]){auto old=expectedPatch[indices[i]];expectedPatch[indices[i]]=uint8_t(values[i]-1);if(save)expectedSnapshot[i]=old;}}else if(kind==2&&previous){for(unsigned i=0;i<16;++i)if(values[i])expectedPatch[indices[i]]=expectedSnapshot[i];}else if(kind==3)expectedBackup=edit;else if(kind==4)expectedEdit=backup;
while(!t.complete()){if(t.awaitingChild()){auto c=t.child();if(c==C::Load)++loads;if(c==C::Apply){++applies;check(t.savePrevious(),"Scene activation must snapshot");}if(c==C::Notify)++notify;check(t.resumeChild(),"Scene childreply");continue;}auto read=[&](S s)->uint32_t{switch(s){case S::ActivateReadBank:return bank;case S::ApplyReadEdit:case S::RestoreReadEdit:case S::BackupReadEdit:case S::CopyReadEdit:return 0xfffffff0;case S::ApplyReadPatch:case S::RestoreReadPatch:return 0xffffffa0;case S::ApplyReadIndex:case S::RestoreReadIndex:return indices[t.index()];case S::ApplyReadValue:case S::RestoreReadEnabled:return values[t.index()];case S::ApplyReadOld:return patch[indices[t.index()]];case S::RestoreReadPrevious:return previous;case S::RestoreReadSelected:return bank;case S::RestoreReadOld:return snapshot[t.index()];case S::BackupRead:return edit[t.index()];case S::CopyRead:return backup[t.index()];default:throw std::runtime_error("Unexpected sceneread");}};auto write=[&](S s,uint32_t v){switch(s){case S::ActivatePublishPrevious:case S::RestorePublishPrevious:storedPrevious=v;break;case S::ApplyPublishValue:case S::RestorePublishValue:patch[indices[t.index()]]=uint8_t(v);check(t.target()==0xffffffa0u+indices[t.index()],"Scene unsigned parameter address");break;case S::ApplyPublishOld:snapshot[t.index()]=uint8_t(v);break;case S::RestorePublishSelected:case S::RestorePublishSelection:selected=v;break;case S::BackupPublish:backup[t.index()]=uint8_t(v);++copyWrites;break;case S::CopyPublish:edit[t.index()]=uint8_t(v);++copyWrites;break;default:throw std::runtime_error("Unexpected scenewrite");}};auto stage=t.stage();auto cost=t.nextClocks(6);check(cost&&t.advanceBefore(cost-1,read,write,[](S){return 6u;})==0&&stage==t.stage(),"Early scene deadline");check(t.advanceBefore(cost,read,write,[](S){return 6u;})==cost,"Scene deadline");}
check(patch==expectedPatch&&snapshot==expectedSnapshot,"Scene exact apply/restore live duplicate order");check(edit==expectedEdit&&backup==expectedBackup,"Scene exact copy64");if(kind==0)check(storedPrevious==bank&&loads==unsigned(bank!=0)&&applies==unsigned(bank!=0),"Scene activation bank decision");if(kind==1)check(notify==1,"Scene notify after allpairs");if(kind==2)check(loads==unsigned(previous!=0)&&selected==bank&&storedPrevious==0,"Scene restore selected/previous");if(kind==3||kind==4)check(copyWrites==64,"Scene copy publicationcount");++cases;};
for(unsigned parameter=0;parameter<256;++parameter)for(unsigned value=0;value<256;++value)for(unsigned save:{0u,1u})for(unsigned duplicate:{0u,1u})verify(1,parameter,value,save,1,1,duplicate);for(unsigned bank=0;bank<256;++bank)for(unsigned previous=0;previous<256;++previous)verify(2,bank,previous,0,bank,previous,bank&1);for(unsigned kind:{0u,3u,4u})for(unsigned value=0;value<256;++value)verify(kind,value,value,value,value,value,value&1);
std::cout<<"PASS: "<<cases<<" pure edit scene/parameter/snapshot-copy tasks, independent live duplicate-parameter/snapshot/restore/bank/copy64 oracles, pointer wrap and early deadlines\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
